import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def workload(x):
    batch, reduce_size, width = x.shape
    block_m = min(256, reduce_size)

    def mean_kernel(x_ref, out_ref):
        step = pl.program_id(2)
        column_sum = jnp.sum(
            x_ref[...], axis=0, dtype=jnp.float32
        ).reshape(1, width)

        @pl.when(step == 0)
        def initialize():
            out_ref[...] = column_sum

        @pl.when(step != 0)
        def accumulate():
            out_ref[...] += column_sum

        @pl.when(step == pl.num_programs(2) - 1)
        def finalize():
            out_ref[...] = out_ref[...] * (1.0 / reduce_size)

    result = pl.pallas_call(
        mean_kernel,
        out_shape=jax.ShapeDtypeStruct((batch, width), jnp.float32),
        grid=(batch, 1, reduce_size // block_m),
        in_specs=[
            pl.BlockSpec(
                (block_m, width),
                lambda b, _, m: (b, m, 0),
            )
        ],
        out_specs=pl.BlockSpec(
            (1, width),
            lambda b, _, __: (b, 0),
        ),
    )(x)
    return result.astype(x.dtype)

