        out_shape=jax.ShapeDtypeStruct(A.shape, A.dtype),
        grid=(m // block_m, n // block_n),
        in_specs=[
            pl.BlockSpec((block_m, block_n), tile_index),
            pl.BlockSpec((1, 1), scalar_index),
        ],
